/** Quick-score access codes: generated by an admin, entered once by a player. */
export const CODE_LENGTH = 6;
export const CODE_ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";   // no I, O, 0, 1: easy to misread

/** What a person typed -> a clean code candidate (upper case, only valid characters, at most 6). */
export const cleanCode = (v: string): string => v.toUpperCase().split("").filter((c) => CODE_ALPHABET.includes(c)).join("").slice(0, CODE_LENGTH);

export const VALIDITY_CHOICES: { label: string; hours: number }[] = [
  { label: "3 jam", hours: 3 }, { label: "12 jam", hours: 12 }, { label: "1 hari", hours: 24 }, { label: "7 hari", hours: 168 }, { label: "30 hari", hours: 720 },
];
export const USE_CHOICES: { label: string; max: number | null }[] = [
  { label: "1 orang", max: 1 }, { label: "5 orang", max: 5 }, { label: "20 orang", max: 20 }, { label: "Tanpa batas", max: null },
];

export type CalcCodeRow = { id: string; code: string; label: string | null; created_at: string; expires_at: string; max_uses: number | null; uses: number; revoked_at: string | null };
export type CodeStatus = "aktif" | "kedaluwarsa" | "dicabut" | "penuh";

/** Order matters: a revoked code stays "dicabut" even after it would have expired. */
export function codeStatus(c: Pick<CalcCodeRow, "expires_at" | "max_uses" | "uses" | "revoked_at">, now: number = Date.now()): CodeStatus {
  if (c.revoked_at) return "dicabut";
  if (new Date(c.expires_at).getTime() <= now) return "kedaluwarsa";
  if (c.max_uses != null && c.uses >= c.max_uses) return "penuh";
  return "aktif";
}
